 public static void Run(){string root="Assets/Shioka/調整Data/Fighter/Awari/";var source=AssetDatabase.LoadAssetAtPath<TrainingMoveSet>(root+"Skill/Moves.asset");if(source.catalog.Length!=20||source.PersistentOwner(source.Find(TrainingCommand.Light))==source)throw new Exception("Catalog owner");string bytes=File.ReadAllText(AssetDatabase.GetAssetPath(source));string path="Assets/__SkillQA_"+Guid.NewGuid().ToString("N")+".asset";GameObject go=null;TrainingMoveSet clone=null;try{var skill=ScriptableObject.CreateInstance<TrainingMoveData>();skill.data=JsonUtility.FromJson<TrainingMove>(JsonUtility.ToJson(source.Find(TrainingCommand.Light)));AssetDatabase.CreateAsset(skill,path);clone=UnityEngine.Object.Instantiate(source);var row=clone.catalog.First(r=>r.asset.data.command==TrainingCommand.Light);row.asset=skill;clone.OnAfterDeserialize();go=new GameObject("Skill authoring QA");go.hideFlags=HideFlags.HideAndDontSave;var a=go.AddComponent<TrainingSpatialAuthoring>();a.moves=clone;a.character=AssetDatabase.LoadAssetAtPath<TrainingApprovedCharacter>(root+"Data/AwariCharacter.asset");a.hurtboxes=AssetDatabase.LoadAssetAtPath<TrainingHurtboxProfile>(root+"Hurtboxes.asset");a.command=TrainingCommand.Light;a.Reload();a.draft.keys[0].visualOffset=new Vector3(0,.1f,.2f);string status=a.Save();if(skill.data.spatialProfile==null||AssetDatabase.GetAssetPath(skill.data.spatialProfile)!=path||skill.data.spatialProfile.keys[0].visualOffset.y!=.1f)throw new Exception("Same skill subasset save: "+status);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceUpdate);var loaded=AssetDatabase.LoadAssetAtPath<TrainingMoveData>(path);if(loaded.data.spatialProfile==null||loaded.data.spatialProfile.keys.Length!=1)throw new Exception("Reload failed");if(File.ReadAllText(AssetDatabase.GetAssetPath(source))!=bytes)throw new Exception("Catalog mutated by spatial save");File.WriteAllText("Temp/skill-data-checks.txt","PASS20 reference-only skill definitions, actual skill owner, isolated spatial draft, same-file subasset save/reload, catalog unchanged");Debug.Log("SKILL_CHECKS same-file spatial save/reload passed");}finally{if(go!=null)UnityEngine.Object.DestroyImmediate(go);if(clone!=null)UnityEngine.Object.DestroyImmediate(clone);AssetDatabase.DeleteAsset(path);}}
